using RaidClipPlugin.Config;
using RaidClipPlugin.Models;
using RaidClipPlugin.Services;
using Xunit;
namespace RaidClipPlugin.Tests;
public sealed class NewAdventureTests
{
 [Fact]public void LootGuideUsesRealDefinitionsAndHidesDivine(){var c=new RpgConfig();var guide=RpgLootLocations.Build(c);Assert.NotEmpty(guide);Assert.DoesNotContain(guide,i=>i.Rarity=="Divine");Assert.All(guide,i=>Assert.All(i.Ranges,r=>Assert.True(r.Max>=r.Min)));}
 [Fact]public void FishBiomesAreUniqueAndMigrationPreservesCustomFish(){var c=new RpgConfig();Assert.Equal(22,c.Zones.Areas.SelectMany(z=>z.Fish).Distinct().Count());Assert.Equal(22,c.Zones.Areas.Sum(z=>z.Fish.Length));foreach(var f in c.FishSpecies)Assert.Contains(f.Id,c.Zones.Get(f.Zone).Fish);c.Zones.FishBiomesVersion=0;c.Zones.Get("sunny_lagoon").Fish=["custom","leviathan"];RpgFishBiomes.Apply(c);Assert.Contains("custom",c.Zones.Get("sunny_lagoon").Fish);Assert.DoesNotContain("leviathan",c.Zones.Get("sunny_lagoon").Fish);var saved=string.Join(',',c.Zones.Get("sunny_lagoon").Fish);RpgFishBiomes.Apply(c);Assert.Equal(saved,string.Join(',',c.Zones.Get("sunny_lagoon").Fish));}
 [Fact]public void ArmorMigrationPreservesRollsAndOnlyAddsOnce(){foreach(var slot in new[]{EquipmentSlot.Helmet,EquipmentSlot.Chest,EquipmentSlot.Gloves,EquipmentSlot.Boots}){var i=new RpgItem{Slot=slot,CoreStatsVersion=1,Rarity=ItemRarity.Eternal,UpgradeLevel=9,Attributes=new(){Armor=42,Power=17,CritChance=7,ArmorPercent=12}};var id=i.InstanceId;Assert.True(RpgCoreStatService.Apply(i));Assert.False(RpgCoreStatService.Apply(i));Assert.Equal(63,i.Attributes.Armor);Assert.Equal(25.5m,i.Attributes.Power);Assert.Equal(7,i.Attributes.CritChance);Assert.Equal(12,i.Attributes.ArmorPercent);Assert.True(i.Attributes.Stamina>0);Assert.Equal(id,i.InstanceId);Assert.Equal(9,i.UpgradeLevel);Assert.Equal(3,i.CoreStatsVersion);}}
 [Fact]public void CombatChancesAddFivePercentagePointsAndPreserveDisabledSources(){Assert.Equal(7,RpgCombatDropRules.Chance(2));Assert.Equal(5.03m,RpgCombatDropRules.Chance(.03m));Assert.Equal(100,RpgCombatDropRules.Chance(99));Assert.Equal(0,RpgCombatDropRules.Chance(0));}
 [Fact]public void EquipmentPowerIgnoresUnequippedItemsAndPerks(){var c=new RpgConfig();var strong=new RpgProfile();var item=new RpgItem{Slot=EquipmentSlot.Weapon,Rarity=ItemRarity.Epic,Attributes=new(){Attack=50}};strong.Inventory.Add(item);strong.Equipment[EquipmentSlot.Weapon]=item.InstanceId;var weak=new RpgProfile();weak.Inventory.Add(item);weak.Perks["damage"]=50;Assert.True(RpgPvpRules.EquipmentPower(strong,c)>RpgPvpRules.EquipmentPower(weak,c));weak.Perks.Clear();Assert.Equal(RpgPvpRules.EquipmentPower(new(),c),RpgPvpRules.EquipmentPower(weak,c));}
 [Fact]public async Task PvpWinnerAndDrawAreAtomicAndCannotPayTwice(){var root=Path.Combine(Path.GetTempPath(),"otter-pvp-new-"+Guid.NewGuid().ToString("N"));try{var store=new ViewerPointStore(root);var c=new RpgConfig();foreach(var id in new[]{"1","2"})await store.ApplyRpgAsync(id,"Synthetic","seed",a=>{a.Points=1000;return new(true);},default);await store.ReserveDuelStakeAsync("1","Synthetic",100,0,100,default,"11111111111141118111111111111111");var draw=await store.ResolveDuelAsync("1","Synthetic","2","Synthetic","1",100,0,10000,100,default,"11111111111141118111111111111111",c);Assert.True(draw.Draw);Assert.Equal(1000,draw.ChallengerBalance);Assert.False((await store.ResolveDuelAsync("1","Synthetic","2","Synthetic","1",100,0,10000,100,default,"11111111111141118111111111111111",c)).Success);await store.ApplyRpgAsync("2","Synthetic","gear",a=>{var i=new RpgItem{Slot=EquipmentSlot.Weapon,Rarity=ItemRarity.Epic,Attributes=new(){Attack=100}};a.Rpg.Inventory.Add(i);a.Rpg.Equipment[EquipmentSlot.Weapon]=i.InstanceId;return new(true);},default);await store.ReserveDuelStakeAsync("1","Synthetic",100,0,100,default,"22222222222242228222222222222222");var won=await store.ResolveDuelAsync("1","Synthetic","2","Synthetic","1",100,0,10000,100,default,"22222222222242228222222222222222",c);Assert.Equal("2",won.WinnerId);Assert.Equal(900,won.ChallengerBalance);Assert.Equal(1100,won.TargetBalance);}finally{if(Directory.Exists(root))Directory.Delete(root,true);}}
}
